export const translations = { en: {}, nl: {}, de: {}, bs: {} };
for (const row of [rows, moreRows, finalRows]
  .map((part) => part.trim())
  .join("\n")
  .split("\n")) {
  const [en, nl, de, bs] = row.split("|");
  if (!en || !nl || !de || !bs) throw new Error("Incomplete translation row");
  translations.en[en] = en;
  translations.nl[en] = nl;
  translations.de[en] = de;
  translations.bs[en] = bs;
}

// English option labels preserve the original capitalization. Values stay canonical.
Object.assign(translations.en, {
  daily: "Daily",
  weekly: "Weekly",
  monthly: "Monthly",
  "per project": "Per project",
  custom: "Custom",
});
